package com.example.consumer;

import software.amazon.awssdk.services.sqs.SqsClient;
import software.amazon.awssdk.services.sqs.model.*;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.net.URI;
import java.util.List;
import java.util.Map;
import com.google.gson.Gson;
import com.google.gson.JsonObject;

public class OrderEventConsumer {

    private static final String QUEUE_URL = System.getenv("SQS_QUEUE_URL");
    private static final String GRAPHQL_ENDPOINT = System.getenv("GRAPHQL_INTERNAL_ENDPOINT");
    private static final HttpClient httpClient = HttpClient.newHttpClient();
    private static final Gson gson = new Gson();

    public static void main(String[] args) {
        SqsClient sqsClient = SqsClient.create();
        System.out.println("Starting SQS consumer for order events...");

        while (true) {
            ReceiveMessageRequest receiveRequest = ReceiveMessageRequest.builder()
                    .queueUrl(QUEUE_URL)
                    .maxNumberOfMessages(10)
                    .waitTimeSeconds(20)
                    .build();

            List<Message> messages = sqsClient.receiveMessage(receiveRequest).messages();

            for (Message message : messages) {
                try {
                    processOrderEvent(message.body());
                } catch (Exception e) {
                    System.err.println("Error processing message: " + e.getMessage());
                    // Write error details to hostPath volume for debugging
                    writeDebugLog(message.body(), e);
                }

                sqsClient.deleteMessage(DeleteMessageRequest.builder()
                        .queueUrl(QUEUE_URL)
                        .receiptHandle(message.receiptHandle())
                        .build());
            }
        }
    }

    private static void processOrderEvent(String messageBody) throws Exception {
        JsonObject event = gson.fromJson(messageBody, JsonObject.class);
        String eventType = event.get("eventType").getAsString();
        String orderId = event.get("orderId").getAsString();
        String customerName = event.has("customerName") ? 
            event.get("customerName").getAsString() : "Unknown";

        if ("ORDER_CREATED".equals(eventType)) {
            enrichOrderWithCustomerData(orderId, customerName);
        } else if ("ORDER_UPDATED".equals(eventType)) {
            updateOrderStatus(orderId, event.get("status").getAsString());
        }
    }

    // VULNERABILITY: customerName is directly interpolated into GraphQL query
    private static void enrichOrderWithCustomerData(String orderId, String customerName) throws Exception {
        // Build GraphQL query with unsanitized user input from SQS message
        String graphqlQuery = String.format(
            "{\"query\": \"{ customer(name: \\\"%s\\\") { id email loyaltyTier creditLimit orders { id total } } }\"}",
            customerName
        );

        HttpRequest request = HttpRequest.newBuilder()
                .uri(URI.create(GRAPHQL_ENDPOINT + "/graphql"))
                .header("Content-Type", "application/json")
                .header("X-Internal-Service", "order-consumer")
                .POST(HttpRequest.BodyPublishers.ofString(graphqlQuery))
                .build();

        HttpResponse<String> response = httpClient.send(request, HttpResponse.BodyHandlers.ofString());

        if (response.statusCode() == 200) {
            JsonObject result = gson.fromJson(response.body(), JsonObject.class);
            // Process enrichment data and persist via secondary mutation
            persistEnrichment(orderId, result);
        }
    }

    private static void updateOrderStatus(String orderId, String status) throws Exception {
        String mutation = String.format(
            "{\"query\": \"mutation { updateOrder(id: \\\"%s\\\", status: \\\"%s\\\") { id status updatedAt } }\"}",
            orderId, status
        );

        HttpRequest request = HttpRequest.newBuilder()
                .uri(URI.create(GRAPHQL_ENDPOINT + "/graphql"))
                .header("Content-Type", "application/json")
                .header("X-Internal-Service", "order-consumer")
                .POST(HttpRequest.BodyPublishers.ofString(mutation))
                .build();

        httpClient.send(request, HttpResponse.BodyHandlers.ofString());
    }

    private static void persistEnrichment(String orderId, JsonObject data) {
        // Writes enrichment to local cache file (uses volume mount)
        String cacheDir = System.getenv("CACHE_VOLUME_PATH");
        if (cacheDir == null) cacheDir = "/var/cache/orders";
        try {
            java.nio.file.Files.writeString(
                java.nio.file.Path.of(cacheDir, orderId + ".json"),
                data.toString()
            );
        } catch (Exception e) {
            System.err.println("Cache write failed: " + e.getMessage());
        }
    }

    private static void writeDebugLog(String messageBody, Exception error) {
        String debugPath = System.getenv("DEBUG_LOG_PATH");
        if (debugPath == null) debugPath = "/var/log/debug";
        try {
            String logEntry = String.format("{\"message\": %s, \"error\": \"%s\"}\n",
                messageBody, error.getMessage());
            java.nio.file.Files.writeString(
                java.nio.file.Path.of(debugPath, "errors.jsonl"),
                logEntry,
                java.nio.file.StandardOpenOption.CREATE,
                java.nio.file.StandardOpenOption.APPEND
            );
        } catch (Exception e) {
            // silently fail
        }
    }
}
